package net.civeira.phylax.feature.observe.observedissue.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.valueobject.IgnoreUntilCountVO;

class IgnoreUntilCountValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of ignore until count of observed issue")
  void test_ignore_until_count_value_holder_assign_plain_value() {
    Object holder = new Object();
    IgnoreUntilCountValueHolder<Object> value = new IgnoreUntilCountValueHolder<>(holder);
    Assertions.assertSame(holder, value.ignoreUntilCount(1), "Setters must return the holder");
    Assertions.assertTrue(value.getIgnoreUntilCountValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getIgnoreUntilCount().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.ignoreUntilCountNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getIgnoreUntilCountValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getIgnoreUntilCount().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of ignore until count of observed issue")
  void test_ignore_until_count_value_holder_assign_value_object() {
    Object holder = new Object();
    IgnoreUntilCountValueHolder<Object> value = new IgnoreUntilCountValueHolder<>(holder);
    IgnoreUntilCountVO vo = IgnoreUntilCountVO.from(1);
    Assertions.assertFalse(value.getIgnoreUntilCountValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.ignoreUntilCount(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getIgnoreUntilCountValue().orElseThrow());
    Assertions.assertSame(holder, value.ignoreUntilCount(Optional.empty()));
    Assertions.assertFalse(value.getIgnoreUntilCountValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.ignoreUntilCount(Optional.of(vo)));
    Assertions.assertSame(vo, value.getIgnoreUntilCountValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of ignore until count of observed issue against the original")
  void test_ignore_until_count_value_holder_read() {
    Object holder = new Object();
    IgnoreUntilCountValueHolder<Object> value = new IgnoreUntilCountValueHolder<>(holder);
    IgnoreUntilCountVO vo = IgnoreUntilCountVO.from(1);
    IgnoreUntilCountVO other = IgnoreUntilCountVO.from(1);
    ObservedIssue original = Mockito.mock(ObservedIssue.class);
    Mockito.when(original.getIgnoreUntilCountValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readIgnoreUntilCount(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readIgnoreUntilCount(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.ignoreUntilCount(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readIgnoreUntilCount(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readIgnoreUntilCount(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of ignore until count of observed issue")
  void test_ignore_until_count_value_holder_unset() {
    Object holder = new Object();
    IgnoreUntilCountValueHolder<Object> value = new IgnoreUntilCountValueHolder<>(holder);
    IgnoreUntilCountVO vo = IgnoreUntilCountVO.from(1);
    value.ignoreUntilCount(vo);
    Assertions.assertSame(holder, value.unsetIgnoreUntilCountIfMatches("ignoreUntilCount_other"));
    Assertions.assertTrue(value.getIgnoreUntilCountValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetIgnoreUntilCountIfMatches("ignoreUntilCount"));
    Assertions.assertFalse(value.getIgnoreUntilCountValue().isPresent(),
        "The field name must clear the value");
    value.ignoreUntilCount(vo);
    Assertions.assertSame(holder, value.unsetIgnoreUntilCount());
    Assertions.assertFalse(value.getIgnoreUntilCountValue().isPresent(),
        "Unset must clear the value");
  }
}
